(1, 1, 'الكتلة لا تفنى ولا تُستحدث، فلا تتغير بنقل المادة أو تغيرها.', '["النسب المتضاعفة تخص مركبين من العنصرين نفسيهما.","","المعطى كتلة لا شحنة.","المعطى كتلة لا طاقة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:21:39.994Z"}'::jsonb),
